//! Weave Fleet's desktop shell, rebuilt in Rune: `[rail][session-list][conversation][content]`
//! and the status bar, drawn from Fleet's own tokens. With no `--server` it draws invented data;
//! given `--server <url>` it shows that Fleet's sessions and conversations (`src/fleet/`).
#[rustfmt::skip] // generated by tools/gen-icons.py
mod icons;
pub mod fleet;
mod mock;
#[cfg(test)]
mod tests;
mod theme;
pub mod view;

use fleet::link::{Connection, Link, Post};
use fleet::model::StreamState;
use mock::{Project, Session, Status};
use rune::{App, AppSpec, Image, ImageCache, Key, KeyEvent, TextEdit, Tx};
use view::conversation::{Message, Part, ToolState};

/// The rail entries, in Fleet's order. Only Sessions is rebuilt; the others show a notice.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Rail {
    Sessions,
    Workflows,
    Automations,
    Analytics,
    GitHub,
    Settings,
}

pub struct State {
    /// `None` follows the system's appearance, as Fleet's default "System" theme does.
    pub dark: Option<bool>,
    pub rail: Rail,
    pub sidebar_open: bool,
    pub sidebar_w: f32,
    pub content_open: bool,
    /// The workspace sheet's measured width; 0 until its first layout.
    pub sheet_w: f32,
    /// The theme the last frame was drawn in, so the theme key can flip what is on screen even
    /// while `dark` still follows the system.
    pub drawn_dark: std::cell::Cell<bool>,
    pub projects: Vec<Project>,
    /// The open session: (project, session).
    pub open: (usize, usize),
    pub filter: TextEdit,
    pub draft: TextEdit,
    /// Seconds since start, from `poll`.
    pub clock: f64,
    /// When the open session's turn started, on `clock`.
    pub working_since: f64,
    /// A canned reply on its way: (project, session, due).
    reply: Option<(usize, usize, f64)>,
    cache: Option<ImageCache>,
    pub logo: Option<Image>,
    /// The Fleet server this window shows, once the connection has started; `None` draws `mock.rs`.
    pub link: Option<Link>,
    pub connection: Connection,
    /// The open session's conversation as the reducer holds it.
    pub stream: Option<StreamState>,
    /// The last thing that went wrong, shown in the status bar.
    pub notice: Option<String>,
    /// Stands in for the open session while the list is empty.
    blank: Project,
}

/// The `--server` address, read once at start so `State::default` can tell it has one.
static SERVER: std::sync::OnceLock<String> = std::sync::OnceLock::new();

impl Default for State {
    fn default() -> Self {
        State {
            dark: None,
            rail: Rail::Sessions,
            sidebar_open: true,
            sidebar_w: view::SIDEBAR_W,
            content_open: false,
            sheet_w: 0.0,
            drawn_dark: std::cell::Cell::new(true),
            projects: if SERVER.get().is_some() { Vec::new() } else { mock::projects() },
            open: (0, 0),
            filter: TextEdit::new(""),
            draft: TextEdit::new(""),
            clock: 0.0,
            working_since: -18.0,
            reply: None,
            cache: None,
            logo: None,
            link: None,
            connection: Connection::Connecting,
            stream: None,
            notice: None,
            blank: Project { name: "Sessions".into(), path: String::new(), open: true, sessions: vec![mock::blank_session()] },
        }
    }
}

impl State {
    pub fn project(&self) -> &Project {
        self.projects.get(self.open.0).filter(|p| self.open.1 < p.sessions.len()).unwrap_or(&self.blank)
    }

    pub fn session(&self) -> &Session {
        self.project().sessions.get(self.open.1).unwrap_or(&self.blank.sessions[0])
    }

    /// Every session in list order, for the previous/next keys.
    fn order(&self) -> Vec<(usize, usize)> {
        self.projects.iter().enumerate().flat_map(|(p, project)| (0..project.sessions.len()).map(move |s| (p, s))).collect()
    }

    fn step(&mut self, by: isize, tx: &mut Tx) {
        let order = self.order();
        if order.is_empty() {
            return;
        }
        let at = order.iter().position(|&id| id == self.open).unwrap_or(0) as isize;
        let (p, i) = order[(at + by).rem_euclid(order.len() as isize) as usize];
        self.open_session(p, i, tx);
    }
}

/// The composer's Send: the message joins the conversation, and a canned reply follows.
pub fn send(s: &mut State, tx: &mut Tx) {
    let text = s.draft.text.trim().to_string();
    if text.is_empty() {
        return;
    }
    // On a server the message goes to the agent, and the conversation shows it when the server
    // says it was received.
    if let (Some(link), Some(id)) = (&s.link, s.open_id()) {
        link.send_prompt(&id, &text);
        s.draft.clear();
        s.notice = None;
        tx.scroll_to_bottom("stream");
        return;
    }
    let (p, i) = s.open;
    let session = &mut s.projects[p].sessions[i];
    let id = format!("u{}", session.messages.len() + 1);
    session.messages.push(Message::user(id, text));
    session.status = Status::Working;
    session.age = "now".into();
    session.dim = 1.0;
    s.draft.clear();
    s.working_since = s.clock;
    s.reply = Some((p, i, s.clock + 2.5));
    tx.scroll_to_bottom("stream");
    tx.wake_after(std::time::Duration::from_millis(2600));
}

/// Esc, and the composer's Interrupt button.
pub fn interrupt(s: &mut State) {
    if let (Some(link), Some(id)) = (&s.link, s.open_id()) {
        if s.session().status == Status::Working {
            link.abort(&id);
        }
        return;
    }
    let (p, i) = s.open;
    let session = &mut s.projects[p].sessions[i];
    if session.status == Status::Working {
        session.status = Status::Idle;
        end_tools(session);
        s.reply = None;
    }
}

/// A turn that ends takes its running tool calls with it.
fn end_tools(session: &mut Session) {
    for part in session.messages.iter_mut().flat_map(|m| m.parts.iter_mut()) {
        if let Part::Tool { state, .. } = part
            && *state == ToolState::Running
        {
            *state = ToolState::Plain;
        }
    }
}

fn poll(s: &mut State, now: f64, tx: &mut Tx) -> bool {
    // Whole seconds only, so the "Working · 18s" label redraws once a second.
    let ticked = now.floor() != s.clock.floor();
    s.clock = now;
    match s.reply {
        Some((p, i, due)) if now >= due => {
            let session = &mut s.projects[p].sessions[i];
            end_tools(session);
            let id = format!("a{}", session.messages.len() + 1);
            let reply = Part::text(format!("{id}-t"), mock::CANNED_REPLY);
            session.messages.push(Message::assistant(id, vec![reply]));
            session.status = Status::Idle;
            s.reply = None;
            tx.scroll_to_bottom("stream");
            true
        }
        _ => ticked && s.session().status == Status::Working,
    }
}

fn on_key(s: &mut State, ev: &KeyEvent, tx: &mut Tx) -> bool {
    if ev.is_command('b') {
        s.sidebar_open = !s.sidebar_open;
    } else if ev.is_command('[') {
        s.step(-1, tx);
    } else if ev.is_command(']') {
        s.step(1, tx);
    } else if ev.is_command('l') && ev.mods.shift {
        // Not a Fleet shortcut: a quick way to see both themes in the prototype.
        s.dark = Some(!s.drawn_dark.get());
    } else if ev.key == Key::Escape {
        interrupt(s);
    } else {
        return false;
    }
    true
}

fn setup(s: &mut State, waker: rune::Waker) {
    let cache = s.cache.insert(ImageCache::new(waker));
    let logo = cache.load(&include_bytes!("../assets/weave_logo.png")[..]);
    // Decoded before the first frame, so a headless snapshot has the logo in it.
    #[cfg(not(target_arch = "wasm32"))]
    let _ = logo.wait();
    s.logo = Some(logo);
}

pub fn spec() -> AppSpec<State> {
    AppSpec {
        min_size: Some((720.0, 480.0)),
        scenes: &[
            ("light", |s| s.dark = Some(false)),
            ("dark", |s| s.dark = Some(true)),
            ("sidebar-closed", |s| s.sidebar_open = false),
            ("content-open", |s| s.content_open = true),
            ("needs-input", |s| s.open = (0, 1)),
            ("automations", |s| s.rail = Rail::Automations),
            ("server-notice", |s| s.notice = Some("Couldn't send the message: connection refused".into())),
        ],
        fonts: &[include_bytes!("../assets/fonts/InterVariable.ttf"), include_bytes!("../assets/fonts/JetBrainsMono-Variable.ttf")],
        families: ("Inter", "JetBrains Mono"),
        setup: Some(setup),
        poll: Some(poll),
        on_key: Some(on_key),
        // The desktop app's own window: 1360 x 880, no smaller than 720 x 480 (`desktop/src/main.ts`).
        ..AppSpec::new("Weave Fleet", (1360.0, 880.0), State::default, view::root)
    }
}

/// The browser build's entry point; the desktop build starts from `main.rs`.
#[cfg_attr(target_arch = "wasm32", wasm_bindgen::prelude::wasm_bindgen(start))]
pub fn start() {
    rune::run(spec());
}

/// The desktop entry point: `--server <url>` shows that Fleet; every other argument is Rune's own
/// (`--snap`, `--script`, ...).
pub fn start_desktop() {
    let (server, rest) = split_args(std::env::args().skip(1));
    if let Some(url) = &server {
        let _ = SERVER.set(url.clone());
    }
    let app = App::new(spec()).args(rest);
    if let Some(url) = server {
        let handle = app.handle();
        let link = Link::start(url, Post::from_handle(handle.clone()));
        handle.update(move |s, _| s.link = Some(link));
    }
    app.run();
}

/// Takes `--server <url>` (or `--server=<url>`) out of the arguments.
pub fn split_args(args: impl Iterator<Item = String>) -> (Option<String>, Vec<String>) {
    let (mut server, mut rest) = (None, Vec::new());
    let mut args = args;
    while let Some(arg) = args.next() {
        if arg == "--server" {
            server = args.next();
        } else if let Some(url) = arg.strip_prefix("--server=") {
            server = Some(url.to_string());
        } else {
            rest.push(arg);
        }
    }
    (server, rest)
}
